# Generated by manage.py generate_test_cases.
from bloomerp.models.users.user import User
from django.urls import reverse
from django.http import HttpResponse
from bloomerp.models.communication import EmailAccount
from bloomerp.models.communication.inbox.inbox import Inbox
from bloomerp.models.communication.inbox.inbox_folder import InboxFolder
from bloomerp.tests.base import (
    BloomerpModelViewTestCase,
    ExpectedResult,
    RequestScenario,
    ModelRequestScenario,
)


class TestBloomerpProfileView(BloomerpModelViewTestCase):
    """Tests class `BloomerpProfileView` from `bloomerp/views/users/profile.py`."""

    view_name = 'my_profile_overview'
    model = User

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Verify sender preferences use the same access checks as composing."""
        return [
            RequestScenario(
                name="An accessible inbox account can become the default",
                method="POST", user=self.normal_user, prepare=self.prepare_accessible_account,
                expected=ExpectedResult(status_code=302, response_validators=self.default_saved),
            ),
            RequestScenario(
                name="An inaccessible account cannot become the default",
                method="POST", user=self.normal_user, prepare=self.prepare_inaccessible_account,
                expected=ExpectedResult(response_validators=self.default_rejected),
            ),
        ]

    def prepare_inaccessible_account(self, scenario: RequestScenario) -> None:
        """Submit a valid profile with an account outside the user's access."""
        self.account = EmailAccount.objects.create(email_address="profile@example.com")
        scenario.data = {
            "first_name": "Ada", "last_name": "Lovelace",
            "date_view_preference": "Y-m-d", "datetime_view_preference": "Y-m-d H:i",
            "default_email_account": str(self.account.pk),
        }

    def prepare_accessible_account(self, scenario: RequestScenario) -> None:
        """Grant sender access through the user's inbox before choosing it."""
        self.prepare_inaccessible_account(scenario)
        inbox = Inbox.objects.create(user=self.normal_user, name="Profile mail")
        InboxFolder.objects.create(inbox=inbox, type="email", related_object_id=str(self.account.pk))

    def default_saved(self, _response: HttpResponse) -> bool:
        """Confirm the user's selected sender was persisted."""
        self.normal_user.refresh_from_db()
        return self.normal_user.default_email_account_id == self.account.pk

    def default_rejected(self, response: HttpResponse) -> bool:
        """Confirm the forged preference produces a field error without saving."""
        self.normal_user.refresh_from_db()
        return self.normal_user.default_email_account_id is None and "default_email_account" in response.context["form"].errors

    def test_profile_layout_renders_and_updates_only_profile_fields(self) -> None:
        """Render editable ApplicationFields and save only the user's profile."""
        self.client.force_login(self.normal_user)
        url = reverse("users_my_profile_overview")
        original_staff_status = self.normal_user.is_staff

        response = self.client.get(url)
        self.assertEqual(response.status_code, 200)
        self.assertContains(response, 'name="first_name"')
        self.assertContains(response, 'name="last_name"')
        self.assertContains(response, 'name="date_view_preference"')
        self.assertContains(response, 'name="datetime_view_preference"')
        self.assertNotContains(response, 'name="is_staff"')

        response = self.client.post(url, {
            "first_name": "Ada",
            "last_name": "Lovelace",
            "date_view_preference": "Y-m-d",
            "datetime_view_preference": "Y-m-d H:i",
            "is_staff": "false" if original_staff_status else "on",
        })
        self.assertEqual(response.status_code, 302)
        self.normal_user.refresh_from_db()
        self.assertEqual(self.normal_user.first_name, "Ada")
        self.assertEqual(self.normal_user.last_name, "Lovelace")
        self.assertEqual(self.normal_user.date_view_preference, "Y-m-d")
        self.assertEqual(self.normal_user.datetime_view_preference, "Y-m-d H:i")
        self.assertEqual(self.normal_user.is_staff, original_staff_status)

        response = self.client.post(url, {
            "first_name": "Ada",
            "last_name": "Lovelace",
            "date_view_preference": "invalid-format",
            "datetime_view_preference": "Y-m-d H:i",
        })
        self.assertEqual(response.status_code, 200)
        self.assertIn("date_view_preference", response.context["form"].errors)
